import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, float, uniform, positionLocal, mix, smoothstep, distance } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-divider';
  group.position.set(-1.25, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const width = 2.2;
  const height = 0.14;
  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  const parallaxOffset = uniform(vec2(0, 0));
  const displacementStrength = uniform(float(0.02));

  const colorTex = texture(colorMap, uv());
  const depthTex = texture(depthMap, uv());

  const displacedPos = positionLocal.add(
    vec3(0, 0, depthTex.r.mul(displacementStrength))
  );

  const centerDist = distance(uv(), vec2(0.5, 0.5));
  const jewelGlow = smoothstep(float(0.08), float(0.0), centerDist);

  const baseColor = colorTex.rgb;
  const accentColor = vec3(1.0, 0.1647, 0.2196); // #ff2a38 approx
  const finalColor = mix(baseColor, accentColor, jewelGlow.mul(0.85));

  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorNode = finalColor;
  material.positionNode = displacedPos;
  material.metalness = 0.5;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.4;
  material.anisotropy = 0.6;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-features-divider-plane';
  group.add(mesh);

  // Center jewel accent (small sphere-ish disc) machined metal look
  const jewelGeo = new THREE.CircleGeometry(0.045, 32);
  const jewelMat = new THREE.MeshPhysicalNodeMaterial();
  jewelMat.colorNode = vec3(1.0, 0.1647, 0.2196);
  jewelMat.metalness = 0.55;
  jewelMat.roughness = 0.35;
  jewelMat.clearcoat = 0.25;
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.z = 0.01;
  jewel.name = 'hub-features-divider-jewel';
  group.add(jewel);

  // Interactivity state
  const basePos = { x: group.position.x, y: group.position.y, z: group.position.z };
  let hovered = false;
  let pressed = false;
  let riseTween = null;
  let pressTween = null;

  const onPointerOver = () => {
    if (hovered) return;
    hovered = true;
    if (riseTween) riseTween.kill();
    riseTween = gsap.to(group.position, {
      y: basePos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onPointerOut = () => {
    hovered = false;
    if (riseTween) riseTween.kill();
    riseTween = gsap.to(group.position, {
      y: basePos.y,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onPointerDown = () => {
    pressed = true;
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  const onPointerUp = () => {
    pressed = false;
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  const onClick = () => {
    if (group.userData.emit) {
      group.userData.emit('hub-features.select');
    }
  };

  // Subtle parallax response via primitives if provided
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { strength: 0.03, target: parallaxOffset });
  }

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
  };

  group.userData.cleanup = () => {
    if (riseTween) riseTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    if (colorMap) colorMap.dispose();
    if (depthMap) depthMap.dispose();
  };

  return group;
}
